import React, { useEffect, useState } from 'react'
import PropertyUnitsTable from './PropertyUnitsTable'
import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import PropertyUnitFormModal from './PropertyUnitFormModal';
import propertiesApi from '../../../api/properties/propertiesApi';
import { Loading } from '../../../components';

const columns = [

    { name: "Title", uid: "title" },
  { name: "Reference", uid: "reference_number" },
    { name: "Property", uid: "property_title" },
    { name: "County", uid: "property_county_title" },
    { name: "Town", uid: "property_town" },
    { name: "Type", uid: "property_unit_type" },
    { name: "Disposal", uid: "disposal_type" },
    { name: "Floor", uid: "floor" },
    { name: "Bedrooms", uid: "bedrooms" },
    { name: "Bathrooms", uid: "bathrooms" },
    { name: "Price", uid: "price" },
    { name: "Payment Current", uid: "is_paid" },
    { name: "Actions", uid: "actions" },
];


function PropertyUnitsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const navigate = useNavigate()
    const [propertyUnit, setPropertyUnit] = useState()
    const [propertyUnits, setPropertyUnits] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)

    const propertyUnitsActionsApi = useApi(propertiesApi.propertiesAction)

    const getPropertyUnits = async () => {
        await propertyUnitsActionsApi.request({
            "action": "GetAllEntityPropertyUnits"

        })
    }


    useEffect(() => {
        getPropertyUnits()
    }, [])


    const handleEditAction = (item) => {
      console.log("to edit ", item);
      setUpdated(false);
      setopenEditModal(true);
      setPropertyUnit(item);
      setmodalTitle(`${item.title}`);
    };

    const handleAddAction = () => {
      setUpdated(false);
      setopenEditModal(true);
      setmodalTitle("Add new property");
      setPropertyUnit(null);
    };
    const handleDetailsAction = (property_unit) => {
      navigate(`/realty/properties/units/details`, {
        state: {
          property_unit: property_unit,
        },
      });
    };
    const handleDeleteAction = (item) => {
      navigate(`/realty/properties/delete/${item.id}`);
    };

    useEffect(() => {
      if (propertyUnitsActionsApi.data && propertyUnitsActionsApi.data.length) {
        setPropertyUnits(propertyUnitsActionsApi.data);
      }

      console.log("preparationsActionsApi.data", propertyUnitsActionsApi.data);
    }, [propertyUnitsActionsApi.data]);

    useEffect(() => {
      getPropertyUnits();
    }, [updated]);

    //Filtering data
    useEffect(() => {
      setdata(propertyUnits);
    }, [propertyUnits]);

    const handleFilter = (e) => {
      const search_param = e;

      if (
        propertyUnits &&
        propertyUnits.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setdata(
          propertyUnits.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(propertyUnits);
      }
    };

    return (
      <div>
        {openEditModal && (
          <PropertyUnitFormModal
            ismodalOpen={openEditModal}
            setisModalOpen={setopenEditModal}
            propertyUnitToEdit={propertyUnit}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {propertyUnitsActionsApi.loading ? (
          <Loading loading={propertyUnitsActionsApi.loading} />
        ) : (
          <PropertyUnitsTable
            data={data}
            columns={columns}
            editAction={handleEditAction}
            detailsAction={handleDetailsAction}
            deleteAction={handleDeleteAction}
            addAction={handleAddAction}
            handleFilter={handleFilter}
            title={"Property Units"}
          />
        )}
      </div>
    );
}

export default PropertyUnitsList